// Settle an already committed native leader update. Never replay or save DWG.
using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Web.Script.Serialization;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.ApplicationServices;using Autodesk.AutoCAD.EditorInput;using App=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class GroundcoverSavedRecoveryV1 {
 public class Host{public int pid;public long created;public string image;}
 public class Config{public Host host;public string loaded_dll,loaded_dll_sha256,session_dir,request,request_sha256,failure,failure_sha256,output_sha256,emergency_sha256,expected,expected_sha256,receipt;public bool test_only;}
 static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=100000000};static BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m);}static bool Same(string a,string b){return String.Equals(Path.GetFullPath(a),Path.GetFullPath(b),StringComparison.OrdinalIgnoreCase);}static object Get(Type t,string n){return t.GetField(n,F).GetValue(null);}static void Set(Type t,string n,object v){t.GetField(n,F).SetValue(null,v);}static object Call(Type t,string n,params object[] a){return t.GetMethod(n,F).Invoke(null,a);}
 static string Shape(Database db,string[] h){return (string)typeof(NativeGroundcoverCreateV1).GetMethod("Shape",F).Invoke(null,new object[]{db,h});}
 static void Write(string p,object x){using(var f=new FileStream(p,FileMode.CreateNew))using(var w=new StreamWriter(f,new System.Text.UTF8Encoding(false)))w.Write(J.Serialize(x));}
 public static string Verify(Config c,out NativeGroundcoverCreateV1.Job job,out NativeGroundcoverCreateV1.Request req){Need(NativeGeometryReadV1.Hash(c.request)==c.request_sha256&&NativeGeometryReadV1.Hash(c.failure)==c.failure_sha256&&NativeGeometryReadV1.Hash(c.expected)==c.expected_sha256,"RECOVERY_EVIDENCE_CHANGED");req=J.Deserialize<NativeGroundcoverCreateV1.Request>(File.ReadAllText(c.request));Need(req.kind=="groundcover_update"&&NativeGeometryReadV1.Hash(req.job_path)==req.job_sha256,"REQUEST_IDENTITY");job=J.Deserialize<NativeGroundcoverCreateV1.Job>(File.ReadAllText(req.job_path));Need(Same(job.receipt,c.failure)&&NativeGeometryReadV1.Hash(job.input)==job.input_sha256&&NativeGeometryReadV1.Hash(job.output)==c.output_sha256,"SOURCE_OUTPUT_IDENTITY");var failed=J.Deserialize<Dictionary<string,object>>(File.ReadAllText(c.failure));Need((string)failed["status"]=="BOUND_MODULE_FAILED"&&(bool)failed["write_started"]&&(bool)failed["committed"]&&!(bool)failed["replayed"]&&((string)failed["error"]).Contains("UPDATE_SAVE_REOPEN_MISMATCH"),"EXACT_FAILURE_REQUIRED");string emergency=(string)failed["emergency"];Need(NativeGeometryReadV1.Hash(emergency)==c.emergency_sha256,"EMERGENCY_CHANGED");Need(job.items.All(x=>x.up_text!=null&&x.down_text==null&&x.grips==null&&!x.scale.HasValue&&!x.rotation.HasValue&&x.text_grip==null),"TEXT_ONLY_RECOVERY_SCOPE");string expected=File.ReadAllText(c.expected);var expectedRows=J.Deserialize<List<Dictionary<string,object>>>(expected);Need(expectedRows.Count==job.items.Length,"EXPECTED_COUNT");foreach(var item in job.items){var row=expectedRows.Single(x=>(string)x["handle"]==item.template_handle);Need((string)row["up"]==item.up_text&&(string)row["down"]==item.expected.down&&(string)row["layer"]==item.layer&&(string)row["type"]=="TDbSymbMultiLeader","EXPECTED_SEMANTICS");}
 foreach(string file in new[]{job.output,emergency})using(var db=new Database(false,true)){db.ReadDwgFile(file,FileOpenMode.OpenForReadAndAllShare,true,"");db.CloseInput(true);Need(CadValueCompareV1.Json(expected,Shape(db,job.items.Select(x=>x.template_handle).ToArray())),"SAVED_NATIVE_RESULT_CHANGED");}return expected;}
 [CommandMethod("HLCADGROUNDCOVERSAVEDRECOVERV1",CommandFlags.Session)]public void Run(){var doc=App.DocumentManager.MdiActiveDocument;var a=doc.Editor.GetString(new PromptStringOptions("\nRecovery manifest: "){AllowSpaces=true});Config c=null;
 try{c=J.Deserialize<Config>(File.ReadAllText(a.StringResult.Trim('"')));Need(!File.Exists(c.receipt),"RECEIPT_EXISTS");NativeGroundcoverCreateV1.Job job;NativeGroundcoverCreateV1.Request req;string expected=Verify(c,out job,out req);if(c.test_only){Write(c.receipt,new{status="ISOLATED_SAVED_NATIVE_RESULT_VERIFIED",replayed=false,files_changed=false});return;}
 var p=System.Diagnostics.Process.GetCurrentProcess();Need(p.Id==c.host.pid&&p.StartTime.ToUniversalTime().ToFileTimeUtc()==c.host.created&&Same(p.MainModule.FileName,c.host.image),"HOST_IDENTITY");var t=AppDomain.CurrentDomain.GetAssemblies().Select(x=>x.GetType("V736BaseSession",false)).Single(x=>x!=null);CadAdapterContractV1.Check(t);Need(Same(t.Assembly.Location,c.loaded_dll)&&NativeGeometryReadV1.Hash(c.loaded_dll)==c.loaded_dll_sha256&&Same((string)Get(t,"dir"),c.session_dir)&&(Document)Get(t,"doc")==doc,"ADAPTER_IDENTITY");Need((bool)Get(t,"blocked")&&!(bool)Get(t,"busy")&&doc.Database.TransactionManager.NumberOfActiveTransactions==0&&!File.Exists(Path.Combine(c.session_dir,"request.json")),"IDLE_HOLD_REQUIRED");Need(Same(Path.GetDirectoryName(c.request),c.session_dir)&&Same(c.receipt,c.failure+".resolution.json"),"RECOVERY_SCOPE");Call(t,"CheckLive",job.input,job.input_sha256);Call(t,"CheckPath",job.output);using(doc.LockDocument())Need(CadValueCompareV1.Json(expected,Shape(doc.Database,job.items.Select(x=>x.template_handle).ToArray())),"LIVE_RESULT_CHANGED");
 Write(c.receipt,new{status="SAVED_STILL_OPEN",output=job.output,sha256=c.output_sha256,pid=p.Id,source_sha256=job.input_sha256,request=c.request,request_sha256=c.request_sha256,job_sha256=req.job_sha256,failure=c.failure,failure_sha256=c.failure_sha256,emergency_sha256=c.emergency_sha256,expected=c.expected,expected_sha256=c.expected_sha256,changes=new{operation="groundcover_update",created=new string[0],updated=job.items.Select(x=>x.template_handle).ToArray(),native_save_reopen_verified=true},recovery=new{status="COMMITTED_GROUNDCOVER_UPDATE_RECOVERED",replayed=false,production_entities_modified=false,original_failure_preserved=true,working_database_context_corrected=true}});
 ((Dictionary<string,string>)Get(t,"approved"))[job.output]=c.output_sha256;var garden=(HashSet<string>)Get(t,"gardenPaths");if(garden.Contains((string)Get(t,"currentPath")))garden.Add(job.output);Set(t,"currentPath",job.output);Set(t,"currentHash",c.output_sha256);Set(t,"blocked",false);Call(t,"State");
 }catch(System.Exception ex){if(c!=null&&!File.Exists(c.receipt))Write(c.receipt,new{status="RECOVERY_FAILED",error=ex.ToString()});}}
}